int pipefd[2];
int result;

// Common pipe2 flags
const int flags = O_CLOEXEC | O_NONBLOCK;

// Creates a pipe that is non-blocking and automatically
// closes file descriptors if an exec call succeeds.
result = pipe2(pipefd, flags);

if (result == 0) {
    // Read end: pipefd[0]
    // Write end: pipefd[1]

    // Use the pipe...

    close(pipefd[0]);
    close(pipefd[1]);
} else {
    // Error handling (result == -1)
}
